import{_ as l,a0 as i,w as o,s as a,I as n,x as u,a1 as p,A as e,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Ubuntu 服務器版與桌面版有什麼區別？ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 服務器版與桌面版有什麼區別？ | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 服務器版與桌面版有什麼區別？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 服務器版與桌面版有什麼區別？ | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20210901 Ubuntu Server vs Desktop- What-s the Difference","title":"Ubuntu 服務器版與桌面版有什麼區別？","tag":"202201","desc":""},"relativePath":"202201/20210901 Ubuntu Server vs Desktop- What-s the Difference.md","filePath":"[post].md"}'),b={name:"202201/20210901 Ubuntu Server vs Desktop- What-s the Difference.md"};function d(m,t,f,U,g,T){const s=i("Link");return o(),a("div",null,[t[28]||(t[28]=n("h1",{id:"ubuntu-服務器版與桌面版有什麼區別",tabindex:"-1"},[u("Ubuntu 服務器版與桌面版有什麼區別？ "),n("a",{class:"header-anchor",href:"#ubuntu-服務器版與桌面版有什麼區別","aria-label":"Permalink to “Ubuntu 服務器版與桌面版有什麼區別？”"},"​")],-1)),t[29]||(t[29]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202201/04/122152zdqkkqqqw6cgcdcq.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=u("當你點擊 ",-1)),p(s,{href:"https://ubuntu.com/"},{default:e(()=>[...t[0]||(t[0]=[u("Ubuntu 網站",-1)])]),_:1}),t[2]||(t[2]=u(" 上的下載按鈕時，它會給你幾個選項。其中兩個分別是 Ubuntu 桌面版和 Ubuntu 服務器版。",-1))]),t[30]||(t[30]=r('<p>這可能會讓新用户感到困惑。為什麼會有兩個（實際上是四個）？應該下載哪一個？Ubuntu 桌面版還是服務器版？它們是一樣的嗎？有什麼區別？</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/ubuntu-server-desktop-download-800x338.webp" alt="Ubuntu 網站給了你多種選擇"></p><p>我將解釋 Ubuntu 的桌面版和服務器版的區別。我還會解釋你應該使用哪個變體。</p><h3 id="ubuntu-桌面版與-ubuntu-服務器版" tabindex="-1">Ubuntu 桌面版與 Ubuntu 服務器版 <a class="header-anchor" href="#ubuntu-桌面版與-ubuntu-服務器版" aria-label="Permalink to “Ubuntu 桌面版與 Ubuntu 服務器版”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/ubuntu-desktop-server.png?resize=800%2C450&amp;ssl=1" alt="Ubuntu 桌面版和服務器版"></p><p>要了解 Ubuntu 桌面版和服務器版的區別，你應該瞭解桌面操作系統和服務器操作系統的區別。</p><h4 id="桌面操作系統" tabindex="-1">桌面操作系統 <a class="header-anchor" href="#桌面操作系統" aria-label="Permalink to “桌面操作系統”">​</a></h4><p><ruby>桌面電腦<rt>Desktop</rt></ruby>是指個人電腦（PC）。桌面電腦操作系統帶有一個圖形用户界面，以便用户可以使用鼠標和鍵盤操作。桌面電腦的主要目的是給你一個系統，可以用來瀏覽網頁、編輯文檔、查看/編輯圖片和視頻、編碼和遊戲。基本上，就是為個人、終端用户或家庭成員提供了一個通用的計算機。</p><p>我在這裏使用桌面電腦這個術語，但這並不意味着它不能用於筆記本電腦。桌面電腦是個人電腦的通用術語。</p><h4 id="服務器操作系統" tabindex="-1">服務器操作系統 <a class="header-anchor" href="#服務器操作系統" aria-label="Permalink to “服務器操作系統”">​</a></h4><p>另一方面，服務器操作系統是專門為託管網站、應用程序、媒體服務器、資料庫等網絡服務而打造的。</p><p>通常情況下，服務器操作系統不帶有圖形界面。如果是基於 Linux 的操作系統，你就得通過終端的命令來使用該系統。</p>',12)),n("p",null,[t[4]||(t[4]=u("這裏的好處是，服務器操作系統不需要（浪費）大量的內存和計算能力，因為它們不使用 ",-1)),p(s,{href:"https://itsfoss.com/what-is-desktop-environment/"},{default:e(()=>[...t[3]||(t[3]=[u("圖形化桌面環境",-1)])]),_:1}),t[5]||(t[5]=u("。除此以外，服務器操作系統的軟件包配置也不同。",-1))]),t[31]||(t[31]=r('<p>現在你對服務器和桌面的區別有了一些瞭解，讓我們看看 Ubuntu 服務器版和桌面版的區別。</p><h4 id="用户界面" tabindex="-1">用户界面 <a class="header-anchor" href="#用户界面" aria-label="Permalink to “用户界面”">​</a></h4><p>Ubuntu 服務器版和桌面版之間最明顯的區別是用户界面。</p><p>Ubuntu 桌面版的特點是採用 GNOME 桌面環境的圖形化用户界面。這使得它在鼠標點擊的幫助下更容易使用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/installing-gui-ubuntu-server-gnome-desktop.png?resize=792%2C597&amp;ssl=1" alt="圖為 Ubuntu GNOME 版的用户界面"></p><p>Ubuntu 服務器版採用<ruby>無頭方式<rt>headless</rt></ruby>運行。你只有在登錄後才會看到一個終端界面。你經常會從其他電腦上通過 SSH 來遠程管理它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/system-restart-required.png?resize=800%2C469&amp;ssl=1" alt="通過 SSH 連接到遠程 Ubuntu 服務器"></p><h4 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h4>',8)),n("p",null,[p(s,{href:"https://itsfoss.com/install-ubuntu/"},{default:e(()=>[...t[6]||(t[6]=[u("由於有了圖形化的安裝程序，將 Ubuntu 作為桌面電腦是很容易的",-1)])]),_:1}),t[7]||(t[7]=u("。你可以創建一個",-1)),t[8]||(t[8]=n("ruby",null,[u("臨場 USB"),n("rt",null,"Live USB")],-1)),t[9]||(t[9]=u("，無需安裝即可體驗桌面版。如果你喜歡，你可以按照屏幕上的指示在幾分鐘內安裝它。",-1))]),t[32]||(t[32]=r('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/02/installing-ubuntu.png?resize=800%2C549&amp;ssl=1" alt="通過圖形化安裝程序安裝 Ubuntu 桌面版"></p><p>將 Ubuntu 作為服務器安裝並不像桌面版那樣簡單。你只能使用終端界面。如果你不熟悉這個流程，即使是最簡單的任務，如連接到 Wi-Fi，也可能是一個困難的任務。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/ubuntu-server-installation.png?resize=800%2C600&amp;ssl=1" alt="Ubuntu 服務器版的安裝"></p><h4 id="應用程序" tabindex="-1">應用程序 <a class="header-anchor" href="#應用程序" aria-label="Permalink to “應用程序”">​</a></h4><p>在 Ubuntu 桌面版中，默認的應用程序集主要針對普通計算機用户。因此，你會發現網頁瀏覽器、辦公套件、媒體播放器、遊戲等。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/gnome-app-arranger.jpg?resize=799%2C450&amp;ssl=1" alt="Ubuntu 中的應用程序"></p><p>Ubuntu 服務器版的應用程序更多的是為運行網絡服務而定製的。而這還不是全部。有些應用程序的配置也是不同的。以 SSH 為例。Ubuntu 服務器預設了 SSH，這樣你就可以輕鬆地從遠程系統連接到它。而在 Ubuntu 桌面版上，你必須明確啓用 SSH 才行。</p><h4 id="硬件要求" tabindex="-1">硬件要求 <a class="header-anchor" href="#硬件要求" aria-label="Permalink to “硬件要求”">​</a></h4><p>由於桌面版具有圖形用户界面，你需要至少 4GB 的內存來運行 Ubuntu 桌面版。磁盤空間至少要有 20GB。</p><p>這就是 Ubuntu 服務器的有趣之處。它沒有圖形化的界面。命令列界面不會消耗大量的系統資源。因此，你可以在 512MB 和 5GB 磁盤空間的機器上輕鬆運行 Ubuntu 服務器。（LCTT 譯註：當然，對於服務器環境來説，內存和磁盤空間是多多益善。）</p><p>服務器上的內存和磁盤空間受制於你所運行的網絡服務。如果一個網絡應用需要至少 2GB 的內存，你就應該有這麼多的內存。但在最簡單的情況下，即使是 512MB 或 1GB 的內存也可以工作。</p><h4 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to “用途”">​</a></h4><p>這是 Ubuntu 桌面版和服務器版之間的主要區別。問問自己，你想把 Ubuntu 用於什麼目的？</p><p>如果是專門用於部署網絡服務，那就選擇 Ubuntu 服務器。請記住，你需要有基本的 Linux 命令列知識來使用終端。</p><p>如果你想把 Ubuntu 作為像 Windows 一樣的普通電腦使用，那就選擇 Ubuntu 桌面版。如果你想用它來學習 Linux 命令，或用於學習的 Docker 或者甚至是簡單的（但是本地的）LAMP 服務器環境，請繼續使用 Ubuntu 桌面。</p><p>對於服務器來説，Ubuntu 服務器版要比 Ubuntu 桌面版好。對於常規的計算機使用，Ubuntu 桌面版是更好的選擇。</p><h4 id="你應該在服務器上使用-ubuntu-桌面版還是在服務器上安裝圖形界面" tabindex="-1">你應該在服務器上使用 Ubuntu 桌面版還是在服務器上安裝圖形界面？ <a class="header-anchor" href="#你應該在服務器上使用-ubuntu-桌面版還是在服務器上安裝圖形界面" aria-label="Permalink to “你應該在服務器上使用 Ubuntu 桌面版還是在服務器上安裝圖形界面？”">​</a></h4><p>是這樣的，Ubuntu 桌面版和服務器版都是 Linux，你可以用 Ubuntu 桌面版作為服務器來託管網頁服務。這沒問題。</p>',18)),n("p",null,[t[11]||(t[11]=u("同樣地，",-1)),p(s,{href:"https://itsfoss.com/install-gui-ubuntu-server/"},{default:e(()=>[...t[10]||(t[10]=[u("你可以在 Ubuntu 服務器上安裝圖形界面",-1)])]),_:1}),t[12]||(t[12]=u("，並以圖形方式使用它。這也是可行的。",-1))]),t[33]||(t[33]=n("p",null,[n("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/installing-gui-ubuntu-server-gnome-desktop-greet.png?resize=798%2C600&ssl=1",alt:"Ubuntu 服務器上的 GUI 登錄"})],-1)),t[34]||(t[34]=n("p",null,"但僅僅因為它可行，並不意味着你應該這麼做。它違背了為服務器和桌面電腦創建不同版本的全部目的。",-1)),t[35]||(t[35]=n("p",null,"你必須付出額外的努力來將服務器版轉換為桌面版，反之亦然。為什麼要承受這種痛苦呢？",-1)),t[36]||(t[36]=n("p",null,"如果你使用 Ubuntu 的目的很明確，那就下載並安裝合適的 Ubuntu 版本。",-1)),t[37]||(t[37]=n("p",null,"我希望這能使圍繞 Ubuntu 桌面版和服務器版的選擇現在更清楚一些。如果你有問題或建議，請利用評論區。",-1)),t[38]||(t[38]=n("hr",null,null,-1)),n("p",null,[t[14]||(t[14]=u("via: ",-1)),p(s,{href:"https://itsfoss.com/ubuntu-server-vs-desktop/"},{default:e(()=>[...t[13]||(t[13]=[u("https://itsfoss.com/ubuntu-server-vs-desktop/",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=u("作者：",-1)),p(s,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>[...t[15]||(t[15]=[u("Abhishek Prakash",-1)])]),_:1}),t[20]||(t[20]=u(" 選題：",-1)),p(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[16]||(t[16]=[u("lujun9972",-1)])]),_:1}),t[21]||(t[21]=u(" 譯者：",-1)),p(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[17]||(t[17]=[u("wxy",-1)])]),_:1}),t[22]||(t[22]=u(" 校對：",-1)),p(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[18]||(t[18]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[25]||(t[25]=u("本文由 ",-1)),p(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[23]||(t[23]=[u("LCTT",-1)])]),_:1}),t[26]||(t[26]=u(" 原創編譯，",-1)),p(s,{href:"https://linux.cn/"},{default:e(()=>[...t[24]||(t[24]=[u("Linux中國",-1)])]),_:1}),t[27]||(t[27]=u(" 榮譽推出",-1))])])}const C=l(b,[["render",d]]);e